/* Photo is temporary; only reviewed nutrition values enter the existing meal log. */
const mealPhotoDialog=document.createElement('dialog');mealPhotoDialog.id='mealPhotoDialog';mealPhotoDialog.setAttribute('aria-labelledby','mealPhotoTitle');document.body.append(mealPhotoDialog);
let mealPhotoData='',mealPhotoItems=[],mealPhotoController=null,mealPhotoDate='';
function openMealPhoto(){mealPhotoDate=selected;mealPhotoData='';mealPhotoItems=[];mealPhotoDialog.innerHTML=`<div class="dialog-head"><h2 id="mealPhotoTitle">تصوير الوجبة</h2><button class="icon-button" data-photo="close" aria-label="إغلاق">×</button></div><p class="sub">صوّر الطبق كاملًا بإضاءة جيدة. الوزن والسعرات تقديرية؛ أضف الوزن الفعلي أو الزيت المستخدم إن كنت تعرفه.</p><div class="quick-buttons"><button class="button" data-photo="camera">فتح كاميرا الموبايل</button><button class="button secondary" data-photo="gallery">اختيار صورة</button></div><input id="mealCamera" type="file" accept="image/*" capture="environment" hidden><input id="mealGallery" type="file" accept="image/*" hidden><img id="mealPhotoPreview" alt="صورة الوجبة المختارة" hidden><label class="field" style="margin-top:16px">تفاصيل تساعد التحليل (اختياري)<textarea id="mealPhotoNote" maxlength="500" placeholder="مثلًا: 150 غ أرز مطبوخ، ملعقة زيت، سأتناول نصف الطبق"></textarea></label><p class="notice">بالضغط على «تحليل الصورة» تُرسل الصورة إلى OpenAI لتقدير القيم. لا نحفظ الصورة في سجلّك؛ يُحفظ فقط ما تراجعه من بيانات الوجبة.</p><button class="button full-width" data-photo="analyze" disabled>تحليل الصورة</button><p id="mealPhotoStatus" role="status"></p><div id="mealPhotoResults"></div>`;mealPhotoDialog.showModal()}
function closeMealPhoto(){mealPhotoController?.abort();mealPhotoController=null;mealPhotoData='';mealPhotoItems=[];mealPhotoDialog.close()}
mealPhotoDialog.addEventListener('cancel',()=>{mealPhotoController?.abort();mealPhotoData=''});
async function prepareMealPhoto(file){if(!file)return;mealPhotoController?.abort();mealPhotoData='';mealPhotoItems=[];const status=$('#mealPhotoStatus'),btn=mealPhotoDialog.querySelector('[data-photo="analyze"]');btn.disabled=true;$('#mealPhotoResults').innerHTML='';$('#mealPhotoPreview').hidden=true;if(file.size>20000000){status.textContent='اختر صورة أقل من 20 ميجابايت.';return}status.textContent='جارٍ تجهيز الصورة…';const objectURL=URL.createObjectURL(file);try{const img=new Image();img.src=objectURL;await img.decode();const scale=Math.min(1,1600/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);mealPhotoData=canvas.toDataURL('image/jpeg',.85);$('#mealPhotoPreview').src=mealPhotoData;$('#mealPhotoPreview').hidden=false;btn.disabled=false;status.textContent='الصورة جاهزة للتحليل.'}catch{status.textContent='تعذر فتح الصورة. جرّب التقاط صورة جديدة أو اختيار JPEG / PNG.'}finally{URL.revokeObjectURL(objectURL)}}
async function analyzeMealPhoto(){if(!mealPhotoData)return;const btn=mealPhotoDialog.querySelector('[data-photo="analyze"]'),status=$('#mealPhotoStatus');btn.disabled=true;status.textContent='جارٍ تقدير مكونات الوجبة…';$('#mealPhotoResults').innerHTML='';mealPhotoController=new AbortController();const controller=mealPhotoController;try{const r=await fetch('/api/food-photo',{method:'POST',credentials:'same-origin',signal:controller.signal,headers:{'content-type':'application/json','x-fitness-account':accountScope},body:JSON.stringify({image:mealPhotoData,note:$('#mealPhotoNote').value})});const body=await r.json();if(!r.ok){const errors={account_changed:'تغير حساب الدخول. أعد تحميل التطبيق قبل التحليل.',no_food:'لم تظهر وجبة واضحة. أعد التصوير من أعلى الطبق.',analysis_not_configured:'خدمة التحليل تحتاج إعدادًا من مالك التطبيق.',service_credentials:'تعذر اتصال خدمة التحليل. يلزم مراجعة إعداد المفتاح.',insufficient_quota:'حساب API المرتبط رفض الطلب بسبب الرصيد أو الفوترة. حد الميزانية المتبقي لا يؤكد توفر الرصيد؛ يلزم مراجعة حساب المفتاح المستخدم في التطبيق.',rate_limited:'تم بلوغ حد طلبات خدمة التحليل مؤقتًا. انتظر دقيقة ثم أعد المحاولة مرة واحدة.',service_limit_unknown:'رفضت الخدمة الطلب بسبب حد استخدام غير محدد. انتظر دقيقة وأعد المحاولة؛ إذا تكررت الرسالة راجع رصيد API وحدود الاستخدام.',slow_down:'انتظر قليلًا قبل محاولة أخرى.',image_too_large:'الصورة كبيرة جدًا؛ اختر صورة أصغر.',sign_in_required:'سجّل الدخول ثم أعد المحاولة.'};throw Error(errors[body.error]||'تعذر تحليل الصورة الآن. أعد المحاولة أو سجّل الوجبة يدويًا.')}mealPhotoItems=body.items;status.textContent='اكتمل التقدير — راجع المكونات والكميات قبل الحفظ.';$('#mealPhotoResults').innerHTML=`<p class="notice">${esc(body.warning)}<br>الأوزان والمكونات المخفية تقديرية وليست قياسًا دقيقًا.</p><div class="table-wrap"><table><thead><tr><th>المكوّن</th><th>وزن غ</th><th>سعرات</th><th>بروتين غ</th><th>كارب غ</th><th>دهون غ</th></tr></thead><tbody>${body.items.map(x=>`<tr><td>${esc(x.name)}</td>${['grams','calories','protein','carbs','fat'].map(k=>`<td>${fmt(x[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="dialog-actions"><button class="button" data-photo="review">مراجعة القيم وحفظ الوجبة</button><button class="button secondary" data-photo="camera">إعادة التصوير</button></div>`}catch(e){if(e.name!=='AbortError')status.textContent=e.message}finally{if(mealPhotoController===controller){btn.disabled=!mealPhotoData;mealPhotoController=null}}}
document.addEventListener('change',e=>{if(['mealCamera','mealGallery'].includes(e.target.id))prepareMealPhoto(e.target.files[0])});
document.addEventListener('click',e=>{const action=e.target.closest('[data-photo]')?.dataset.photo;if(!action)return;if(action==='open')openMealPhoto();if(action==='close')closeMealPhoto();if(action==='camera')$('#mealCamera').click();if(action==='gallery')$('#mealGallery').click();if(action==='analyze')analyzeMealPhoto();if(action==='review'&&mealPhotoItems.length){const items=mealPhotoItems,values=Object.fromEntries(['grams','calories','protein','carbs','fat'].map(k=>[k,Math.round(items.reduce((s,x)=>s+x[k],0)*10)/10]));const record={date:mealPhotoDate,time:timeNow(),food:items.map(x=>`${x.name} (${fmt(x.grams)} غ تقديري)`).join('، ').slice(0,500),...values};closeMealPhoto();openForm('meal',record,true);$('#recordForm').elements.date.value=mealPhotoDate;$('#fields').insertAdjacentHTML('afterbegin','<input type="hidden" name="photoEstimate" value="1"><p class="notice field full">القيم التالية تقدير من صورة. راجع المكونات والوزن والسعرات ثم اضغط حفظ. تعديل الوزن وحده لا يعيد حساب القيم الغذائية.</p>')}});
